parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "is_offer_stage": {
      "type": "boolean",
      "description": "Whether this email represents a formal settlement offer or counter-offer with explicit proposal language and offer mechanics"
    },
    "is_fr_assessment": {
      "type": "boolean",
      "description": "Whether this email represents an insurer's fair and reasonable assessment or assessment notification (evaluation/analysis of claim, may include amounts)"
    },
    "is_settlement_acceptance": {
      "type": "boolean",
      "description": "Whether this email confirms acceptance/settlement of a previous offer"
    },
    "assessed_amount": {
      "type": "number",
      "description": "The dollar amount mentioned in F&R assessment (if is_fr_assessment = TRUE). Otherwise 0"
    },
    "references": {
      "type": "array",
      "description": "Array of all reference-like numbers found in subject and body (vehicle rego, claim numbers, reference numbers, etc.)",
      "items": {
        "type": "string"
      }
    },
    "total_offer_amount": {
      "type": "number",
      "description": "Total settlement/offer/counter-offer/acceptance amount (if is_offer_stage OR is_settlement_acceptance = TRUE). Otherwise 0"
    },
    "date_received": {
      "type": "string",
      "description": "Date the email was received in YYYY-MM-DD HH:mm:ss format"
    },
    "next_task_due": {
      "type": "string",
      "description": "Next task due date (date_received + 7 days in dd-MMM-yy format)"
    },
    "is_calderbank": {
      "type": "boolean",
      "description": "Whether this is a Calderbank offer or Without Prejudice communication"
    },
    "file_notes": {
      "type": "string",
      "description": "A chronological entry capturing the current status and next required action, formatted as [Date] - [Tag] - [Details]"
    },
    "summary": {
      "type": "string",
      "description": "Brief summary of the email content"
    }
  },
  "required": ["is_offer_stage", "is_fr_assessment", "is_settlement_acceptance", "references", "summary"]
}

parameters.text:
=Subject: {{ $json.subject }}
Firm Domain: example.com
Sender Email: {{ $json.from.value[0].address }}
Recipient Email: {{ $json.to.value[0].address }}
Body: {{ $json.text }}
Received Date: {{ $json.date }}

parameters.jsCode:
const source = $input.first().json.output;

const references = $input.first().json.output.references;
const targetSheets = [
  'Liability',
  'Nat',
  'Cherie',
  'Angelene',
  'Tina',
  'NRMA/Justin',
];

const results = [];

for (const current_reference of references) {
  for (const targetSheet of targetSheets) {
    const { references, ...cleanSource } = source;

    results.push({
      json: {
        ...cleanSource,
        current_reference,
        targetSheet,
      },
    });
  }
}

return results;
